		return {
			root,
			update(e, i) {
				ring.rotation.y = i.time * 1.4;
				ring.position.y = 36 + Math.sin(i.time * 2) * 3;
				ring2.rotation.y = -i.time * 2;
				emitter.visible = i.built >= 1;
			},
		};
